"""Build the Base source inspection, component, density and cost review."""
import html,json,sys
from pathlib import Path


def main():
    out=Path(sys.argv[1]).resolve();a=json.loads((out/'audit.json').read_text());v=json.loads((out/'analysis.json').read_text())
    items=[(4527988,'Lower outer housing'),(4268930,'Top crossbar'),(4756187,'Small module back shell'),(4392221,'Tall cover'),(4594338,'Module frame'),(4664029,'Module backing shell'),(4099408,'Small module front')]
    lookup={u['source_id']:u for u in v['units']};options=''.join(f'<option value="{i}">{label} · #{source}</option>' for i,(source,label) in enumerate(items));unit_panels=[]
    for i,(source,label) in enumerate(items):
        u=lookup[source];path=html.escape(str(out/f'unit-{source}.png'))
        unit_panels.append(f'<section class="unit" id="unit-{i}" '+('' if i==0 else 'hidden')+f'><p><b>{u["triangles"]:,} triangles</b> · {u["faces"]:,} source faces · largest span {u["max_span_mm"]:.0f} mm</p><img src="{path}" alt="Original source unit {source}"><p class="note">{u["not_observed_in_external_views"]:,} triangles not observed by the exterior view sampling. The complete unit is rendered here. Description is an inspection label, not a motion binding.</p></section>')
    paths={name:html.escape(str(out/name)) for name in ('view-15-2.png','costs.png','density.png','heavy-units.png')}
    page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#17202f)}h3{margin:15px 0 8px;font-size:17px}p{margin:8px 0}.note{font-size:12px;color:var(--muted-foreground,#667085)}.stats{display:flex;gap:20px;flex-wrap:wrap}.stats strong{font-size:23px;display:block}.stats span{font-size:12px}nav{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}button,select{font:inherit;border:1px solid var(--border,#aaa);padding:7px;background:var(--background,white);color:inherit;border-radius:6px;cursor:pointer}button[aria-pressed=true]{border-color:var(--primary,#4686d1)}img{display:block;width:100%;height:auto;border-radius:var(--radius,6px)}.overview{max-height:440px;width:auto;max-width:100%;margin:0 auto}.unit img{max-height:430px;object-fit:contain}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td{padding:5px 0;border-bottom:1px solid var(--border,#ddd)}td:last-child{text-align:right}[hidden]{display:none!important}ol{padding-left:22px}li{margin:5px 0}
</style></head><body><h3>Original RMUC 2027 Base</h3><div class="stats"><div><strong>709,354</strong><span>triangles per model</span></div><div><strong>1,418,708</strong><span>across two placed Bases</span></div><div><strong>340</strong><span>source solids / shells</span></div></div><p class="note">Native 0.4 mm / 0.25 rad meshing · 16,811 source faces, all retained. The two Bases already share one definition. No geometry or runtime asset changed.</p><nav id="tabs"><button aria-pressed="true" onclick="show('overview',this)">Original Base</button><button onclick="show('units',this)">Heavy source units</button><button onclick="show('density',this)">Density</button><button onclick="show('costs',this)">Cost & visibility</button></nav><section class="tab" id="overview"><img class="overview" src="'''+paths['view-15-2.png']+'''" alt="Complete original Base"><p class="note">Original source pose and diffuse colors; unresolved local paint uses tagged neutral fallback. LEDs and armor geometry are untouched.</p></section><section class="tab" id="units" hidden><select aria-label="Source unit" onchange="document.querySelectorAll('.unit').forEach((x,i)=>x.hidden=i!=this.value)">'''+options+'''</select>'''+''.join(unit_panels)+'''</section><section class="tab" id="density" hidden><img src="'''+paths['density.png']+'''" alt="Front and top centroid density projections"><p class="note">25 × 25 mm cells. All triangles, including internal and vertical surfaces; each projection reconciles to 709,354.</p></section><section class="tab" id="costs" hidden><img src="'''+paths['costs.png']+'''" alt="Source-unit triangle counts and sampled visibility"><p class="note">26 exterior views at 1600² pixels, one source pose. 79.4% were never frontmost at a sampled pixel; this includes occluded, edge-on and subpixel triangles. It is not a removable-geometry budget.</p></section><h3>What drives the cost</h3><table><tr><td>Lower housing + top crossbar</td><td>310,110 · 43.7%</td></tr><tr><td>Cylindrical faces with radius ≤3 mm</td><td>262,099 · 36.9%</td></tr><tr><td>Two heavily trimmed flat housing faces</td><td>37,819 · 685 inner loops</td></tr><tr><td>Whole units ≤20 mm across</td><td>52,333 · 7.4%</td></tr></table><p class="note">These categories overlap. Many small details live inside large source bodies; removing standalone fasteners alone would leave most geometry.</p><h3>Best next pass</h3><ol><li><b>Top crossbar first:</b> inspect small bores, countersinks and seams in its 144,438 triangles while retaining the outer profile and artwork.</li><li><b>Lower outer housing next:</b> select individual nonfunctional trim loops and rebuild their backing; preserve the larger openings.</li><li><b>Protect module fronts and LEDs:</b> give backing/mounting detail separate quality, and validate hidden candidates across reviewed moving poses.</li></ol><p class="note">Additional whole-unit instancing is secondary here: 51 conservative candidate groups represent 23,564 potentially redundant triangle-payload uses, before correspondence and appearance validation. It would preserve placed triangles.</p><script>function show(id,b){document.querySelectorAll('.tab').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('#tabs button').forEach(x=>x.setAttribute('aria-pressed',x===b));}console.assert(document.querySelectorAll('.unit').length===7);console.log('Base review: seven isolated units, four inspection tabs; all original geometry retained.');</script></body></html>'''
    (out/'review.html').write_text(page);print(out/'review.html')
if __name__=='__main__':main()
